NAME = 'NlCanisius1939: Petrus Canisius Translation'
BOOK = 'Wisdom'

CHAPTERS = {
    1: {
        1: 'Bemint de gerechtigheid, gij heersers der aarde: Houdt den Heer voor ogen in rechtschapenheid, En zoekt Hem in oprechtheid des harten.',
        2: 'Want Hij laat Zich vinden door wie Hem niet beproeven, En openbaart Zich aan die Hem niet wantrouwen.',
        3: 'Gedachten van wantrouwen toch trekken van God af; Beproeft men zijn almacht, dan verslaat zij de dwazen.',
        4: 'Neen, in een arglistige ziel treedt de wijsheid niet binnen; Zij woont niet in een lichaam, in de macht der zonde.',
        5: 'Want de heilige geest der tucht vlucht alle onoprechtheid, Keert zich af van zondige gedachten, En trekt zich terug, als de ongerechtigheid nadert,',
        6: 'Zeker, de wijsheid is een geest vol mensenliefde; Maar zij laat den lasteraar niet ongestraft voor zijn taal. Want God is getuige van zijn nieren, Waarachtige bespieder van zijn hart, En beluisteraar van zijn tong.',
        7: 'Ja, de geest des Heren vervult het heelal; Alles samenhoudend, draagt Hij kennis van ieder woord.',
        8: 'Daarom blijft niemand verborgen, die goddeloos spreekt; De straffende rechtvaardigheid gaat hem niet voorbij.',
        9: 'Want zelfs de gedachten van den zondaar worden ontleed; Het gerucht van zijn woorden dringt door tot den Heer, Zodat zijn zonden worden bestraft.',
        10: 'Een naijverig oor toch verneemt alle geluid; Zelfs het zachtste gemompel blijft niet verborgen.',
        11: 'Wacht u dus wel voor nutteloos morren, En behoedt uw tong voor de laster; Want zelfs heimelijk spreken blijft niet ongestraft, En een mond, die lastert, brengt dood aan de ziel.',
        12: 'Zoekt toch niet de dood door uw verkeerde wandel; Berokkent u geen verderf door de werken van uw handen.',
        13: 'Want het is niet God, die de dood heeft gemaakt; Hij vindt geen vreugde in de ondergang van de levenden.',
        14: 'Hij toch heeft alles geschapen om te leven, En de schepselen der aarde helpen mee. Geen verderfbrengend gift bevindt zich daarin, Zelfs het dodenrijk heeft geen macht op aarde;',
        15: 'Want de gerechtigheid is onsterfelijk.',
        16: 'Maar de goddelozen roepen de dood met daden en woorden, Ze smachten er naar, als was hij een vriend; Ze hebben met hem een verbond gesloten, Omdat ze verdienen, zijn buit te worden.',
    },
    2: {
        1: 'Want ze zeggen tot elkander in valse waan: Ons leven is maar kort en vol verdriet; Geen redmiddel, als het einde van den mens is gekomen; Nooit heeft men van iemand gehoord, die uit het dodenrijk redt.',
        2: 'Ja, bij toeval is het, dat wij ontstonden, En later zal het zijn, als hadden wij nooit bestaan; Want rook is de adem in onze neus, Ons denken een vonk, ontslagen aan ons hart.',
        3: 'Dooft ze uit, het lichaam vergaat tot stof, En de geest vervliegt als ijle lucht;',
        4: 'Onze naam wordt spoedig vergeten, En niemand denkt er meer aan onze werken. Zo snelt ons leven voorbij als een drijvende wolk, En lost zich op als een nevel, Die door de stralen van de zon wordt verdreven, Tot neerslaan gebracht door haar gloed.',
        5: 'Ja, ons leven is een vluchtige schaduw, En ons einde kan niet worden herroepen; Want het wordt verzegeld, en niemand keert terug.',
        6: 'Komt dan, laat ons profiteren van het goed, dat wij hebben, En flink van de wereld genieten, zolang wij nog jong zijn;',
        7: 'Verzadigen wij ons met kostbare wijn en met zalven, Geen lentebloesem mag ons ontgaan!',
        8: 'Omkransen wij ons met rozenknoppen, eer ze verwelken,',
        9: 'Geen hof blijve verstoken van ons pleizier. Overal willen wij de sporen achterlaten van onze vreugd; Want dit is ons deel, en dit komt ons toe.',
        10: 'Wij willen den armen vrome verdrukken, geen weduwe sparen, Noch het witte haar van den hoogbejaarden grijsaard ontzien.',
        11: 'Onze kracht zal de maatstaf zijn van wat recht is; Want het zwakke bewijst zijn eigen nutteloosheid.',
        12: 'Wij willen den vrome belagen, want hij is ons tot last, En verzet zich tegen ons doen. Hij beschuldigt ons van wetsovertreding, En verwijt ons, dat wij misdoen tegen de tucht.',
        13: 'Hij beroemt er zich op, kennis van God te bezitten, En noemt zichzelf een kind van den Heer.',
        14: 'Hij is ons een aanklacht van onze gezindheid, Reeds zijn aanblik strekt ons tot last;',
        15: 'Want zijn leven wijkt af van dat der anderen, Zijn wegen zijn geheel verschillend.',
        16: 'Wij gelden voor hem als valse munt, Hij mijdt onze wegen als drek; Het einde der rechtvaardigen prijst hij gelukkig, En trots noemt hij God zijn vader.',
        17: 'Wij willen eens zien, of zijn woorden waar zijn, En de proef nemen, hoe het wel met hem afloopt.',
        18: 'Want is de rechtvaardige Gods zoon, dan zal Hij hem helpen, En uit de hand van zijn vijanden redden.',
        19: 'Met smaad en mishandeling zullen wij hem beproeven, Om zijn zachtmoedigheid te zien, zijn geduld te toetsen.',
        20: 'Wij willen hem veroordelen tot een schandelijke dood; Want hij wordt toch gered, zo beweert hij.',
        21: 'Zo denken ze, maar ze dwalen; Want hun boosheid maakt hen blind;',
        22: 'Ze hebben geen begrip van Gods geheimen, Verwachten geen loon voor heiligheid, En geloven niet in een kroon voor vlekkeloze zielen.',
        23: 'Toch heeft God den mens geschapen voor onsterfelijkheid, En hem gemaakt als een beeld van zijn Wezen.',
        24: 'Maar de afgunst van den duivel bracht de dood in de wereld;',
        25: 'Die hèm toebehoren, zullen hem smaken.',
    },
    3: {
        1: 'Maar de zielen der rechtvaardigen zijn in Gods hand; Geen kwelling kan hen deren.',
        2: 'In het oog der dwazen was het, of zij stierven; Men beschouwde hun einde wel als een ramp,',
        3: 'En hun heengaan van ons als het einde van alles: Maar toch zijn zij in vrede.',
        4: 'Want al scheen het voor de mensen, dat ze werden gestraft, Toch is het de onsterfelijkheid, die hen wacht,',
        5: 'En na die korte kastijding worden ze rijkelijk beloond. Want God was het, die hen beproefde En hen Zijner waardig bevond;',
        6: 'Als goud in de smeltoven heeft Hij hen beproefd, Maar als een aangenaam brandoffer hen aanvaard.',
        7: 'Als de tijd van hun vergelding komt zullen zij schitteren Als sprankelende vonken in een stoppelveld;',
        8: 'Zij zullen de volkeren richten en de naties beheersen, En de Heer zal hun koning zijn voor eeuwig.',
        9: 'Die op Hem hopen, zullen zijn trouw ondervinden, En die Hem trouw zijn, in zijn liefde verblijven; Want genade en erbarming vallen zijn uitverkorenen ten deel.',
        10: 'Maar de zondaars worden naar hun gezindheid bestraft, Omdat ze den vrome verachten en den Heer verlaten.',
        11: 'Want ongelukkig, wie wijsheid en tucht versmaden! Ijdel is hun hoop en hun zwoegen vergeefs, Nutteloos zijn hun werken;',
        12: 'Hun vrouwen zijn onbezonnen, Hun kinderen slecht;',
        13: 'Vervloekt is hun geslacht! Maar gelukkig de kinderloze, die haar reinheid bewaart, En haar sponde zondeloos weet: Bij de vergelding der zielen oogst zij haar vrucht!',
        14: 'Zo ook de eunuch, die geen boosheid bedrijft, En geen kwaad begeert tegen den Heer; Want een heerlijk loon ontvangt hij voor zijn trouw, Een kostelijk aandeel in de tempel des Heren.',
        15: 'Overheerlijk toch is de vrucht der goede werken, En de wortel der wijsheid blijft onvergankelijk.',
        16: 'Maar de kinderen van echtbrekers gedijen niet; Kroost, dat in zonde verwekt is, gaat te gronde.',
        17: 'Al leven ze ook lang, ze zijn niet in tel, En eerloos is ten slotte hun ouderdom;',
        18: 'En sterven ze jong, ze hebben geen hoop, Geen vertroosting op de dag van het oordeel.',
        19: 'Want rampzalig is het einde van een boos geslacht!',
    },
    4: {
        1: 'Beter kinderloosheid, verbonden met deugd; Want deze blijft onsterfelijk in de herinnering, Daar zij geacht wordt door God en de mensen.',
        2: 'Zolang zij er is, volgt men haar na, En is zij heengegaan, men voelt het gemis; Voor eeuwig triomfeert zij, de lauwerkrans dragend, Omdat zij door smetteloos strijden de kamp heeft gewonnen.',
        3: 'Maar het grote kindertal zal den zondaar niet baten: Door de onechte spruiten slaat het geen diepe wortels. En kan het geen vaste grondslag vinden.',
        4: 'Al schiet het ook een tijdlang nieuwe loten, Het staat toch niet vast, en wordt geschud door de storm; En door de kracht van de winden wordt het ontworteld.',
        5: 'Aan alle kanten worden zijn jonge loten gebroken, Hun vrucht is ongenietbaar, te wrang om te eten, En nergens voor te gebruiken.',
        6: 'Ja, kinderen, uit zondige omgang geboren, Getuigen bij het oordeel tegen het misdrijf der ouders.',
        7: 'Maar de vrome vindt rust, al sterft hij vroeg.',
        8: 'Want niet om lange levensduur is de ouderdom eervol, Niet naar het aantal der jaren wordt hij berekend;',
        9: 'Maar wijsheid is voor de mensen grijze haren, Een smetteloos leven hoge ouderdom.',
        10: 'Daar hij Gode welgevallig was, werd hij bemind, Daar hij tussen zondaars leefde, werd hij opgenomen:',
        11: 'Weggerukt, opdat het kwaad niet zijn geest zou bederven, Of bedrog niet zijn ziel zou verleiden.',
        12: 'Want de betovering van het kwaad verduistert het goede, En de roes der lusten bederft de onschuldige geest.',
        13: 'Vroeg voleindigd, heeft hij vele jaren bereikt;',
        14: 'Want zijn ziel was den Heer welgevallig, En daarom nam Hij hem ijlings weg uit het kwaad. Maar de mensen, die het zagen, verstonden het niet, En kwamen niet op de gedachte:',
        15: 'Dat over zijn geliefden genade en erbarming komen, En zegenrijke vergelding over zijn heiligen.',
        16: 'Maar de vrome stelt zijn dood boven het leven der bozen, Zijn vroeg beëindigde jeugd boven de hoge ouderdom der zondaars.',
        17: 'Want dezen zien wel het eind van den wijze, Maar begrijpen niet, wat de Heer met hem voor heeft, En waarom Hij hem in veiligheid bracht.',
        18: 'Ze zien het en geven hun verachting te kennen, Maar de Heer lacht ze uit.',
        19: 'Eens toch worden ze een eerloos lijk, Een spot onder de doden voor eeuwig; Want Hij slaat ze ter aarde neer in verstomming, En rukt ze van hun grondvesten los. Dan worden ze geheel weggevaagd; Ze zullen pijn moeten lijden, En hun gedachtenis zal vergaan.',
        20: 'Bij de afrekening van hun zonden verschijnen ze met angst, En hun eigen misdaden treden als getuigen tegen hen op.',
    },
    5: {
        1: 'Dan staat de rechtvaardige met groot vertrouwen Tegenover hen, die eens hem verdrukten, En verachtelijk neerzagen op zijn zwoegen.',
        2: 'Dezen zullen bij dat gezicht van grote vreze worden bevangen, Geheel ontsteld over dat onverwachte heil;',
        3: 'Ze zullen tegen elkander zeggen, met rouw in het hart, En in hun zielsangst zuchten:',
        4: 'Dit is nu de man, dien wij vroeger bespotten Als een toonbeeld van hoon, wij verdwaasden. Wij hebben zijn leven voor waanzin gehouden, En zijn einde voor eerloos;',
        5: 'Hoe wordt hij nu onder de kinderen Gods geteld, En deelt hij het lot van de heiligen!',
        6: 'Wij dwaalden dus af van de weg der waarheid; Het licht van de deugd verlichtte ons niet, En de zon ging niet over ons op.',
        7: 'Wij tobden ons af op de wegen van zonde en verderf, Trokken ongebaande woestijnen door, Maar de weg des Heren kenden wij niet!',
        8: 'Wat baatte ons dan die overmoed; Wat hebben geld en grootdoen ons gebracht?',
        9: 'Het ging alles voorbij als een schaduw, Voorbij als een loos gerucht;',
        10: 'Als een schip, dat de golvende wateren klieft, Zonder dat men een spoor van zijn doortocht kan vinden, Of een pad van zijn kiel in de baren.',
        11: 'Of zoals men bij een vogel, die vliegt door de lucht, Geen enkel teken meer vindt van zijn weg: De ijle lucht wordt gezwiept door het slaan van zijn vleugels En gekliefd door de kracht van zijn vlucht; Met klapperende wieken trekt hij er door, Daarna wordt geen spoor van zijn tocht meer gevonden.',
        12: 'Of zoals een pijl, naar het doel geschoten, De lucht doorklieft, die terstond zich weer sluit, Zodat men zijn baan niet kan zien:',
        13: 'Zó zijn wij geboren en ook weer gestorven, Zonder een spoor te kunnen tonen van deugd; Midden in onze boosheid overviel ons het einde.',
        14: 'Ja, de hoop van den zondaar is als kaf, meegesleurd door de wind, Als het lichte schuim, voortgedreven door de storm, Als rook, door een windvlaag verspreid; Ze vervliegt als de herinnering aan een gast van één dag.',
        15: 'Maar de rechtvaardigen blijven eeuwig leven; Bij den Heer vinden zij hun loon, De Allerhoogste zorgt voor hen.',
        16: 'Daarom zullen zij het rijk der glorie ontvangen, En een heerlijke kroon uit de hand van den Heer; Want Hij beschermt hen met zijn rechterhand, En beschut hen met zijn arm.',
        17: 'Hij neemt zijn ijverzucht als pantser, En bewapent de schepping om den vijand te straffen;',
        18: 'Als harnas gordt Hij zijn rechtvaardigheid aan, En zet zijn onfeilbaar oordeel op als helm;',
        19: 'Hij neemt zijn onoverwinlijke heiligheid als schild,',
        20: 'Scherpt zijn strenge gramschap tot zwaard, En het heelal strijdt met Hem mee tegen de dwazen.',
        21: 'De welgemikte pijlen van de bliksem schieten neer, Vliegen van de strakgespannen wolkenboog naar hun doel,',
        22: 'En grimmige hagelstenen worden uit de slinger geworpen; De wateren der zee storten zich kokend over hen uit, En de stromen bruisen onstuimig aan;',
        23: 'De adem van den Almachtige steekt tegen hen op, En jaagt hen uiteen als een orkaan. Zo maakt boosheid de aarde tot een woestenij, En werpt ongerechtigheid de tronen van vorsten omver!',
    },
    6: {
        1: 'Hoort dan, koningen, en luistert, Geeft acht, gij, die geheel de aarde bestuurt;',
        2: 'Leent uw oor, gij, die heerst over velen, En groot gaat op het getal uwer onderdanen!',
        3: 'Want uw macht werd u gegeven door den Heer, En uw heerschappij door den Allerhoogste. Hij zal uw daden nagaan en uw plannen doorvorsen;',
        4: 'Want ofschoon gij dienaren van zijn koningschap zijt, Hebt gij niet recht geregeerd, niet de wet onderhouden, En niet gewandeld naar Gods wil.',
        5: 'Vol verschrikking treedt Hij weldra tegen u op; Want hooggeplaatsten wacht een zeer streng gericht.',
        6: 'De mindere toch verdient vergeving en medelijden, Maar de meerdere wordt des te strenger gestraft.',
        7: 'Ja, Hij, die de Heer is van allen, vreest niemand, Voor geen grootheid is Hij beducht; Want groot en klein heeft Hij geschapen, Hij zorgt op gelijke wijze voor allen:',
        8: 'Maar de machtigen wacht eens een streng onderzoek.',
        9: 'Tot u dus, vorsten, zijn mijn woorden gericht, Opdat gij wijsheid leert en niet ten val komt.',
        10: 'Want wie het heilige heilig behandelt, wordt heilig, En wie dit geleerd heeft, kan verantwoording geven.',
        11: 'Luistert dus gretig naar mijn woorden, Hoort ze verlangend aan; dan wordt gij wijs.',
        12: 'Schoon is de wijsheid, nimmer verwelkt zij; Wie haar beminnen, krijgen haar gemakkelijk te zien. Wie haar zoeken, zullen haar vinden;',
        13: 'Zij voorkomt zelfs die wens, en vertoont zich het eerst.',
        14: 'Wie vroeg om haar opstaat, behoeft zich niet te vermoeien; Want hij vindt haar zitten voor zijn deur.',
        15: 'Naar haar te verlangen is het toppunt van doorzicht, En wie zich geen slaap om haar gunt, is dra zonder zorgen;',
        16: 'Want zelf gaat zij rond en zoekt, wie haar waard zijn, Vertoont zich vriendelijk aan hen op hun wegen, En treedt hun tegemoet bij iedere gedachte.',
        17: 'Want haar aanvang is oprecht verlangen naar tucht,',
        18: 'En verlangen naar tucht is liefde; Liefde is het onderhouden van haar geboden, Het onderhouden der geboden onderpand van onsterfelijkheid,',
        19: 'En onsterfelijkheid brengt in de nabijheid van God:',
        20: 'Zo voert het verlangen naar wijsheid tot het koningschap!',
        21: 'Als dus tronen en schepters u behagen, vorsten der volken, Eert dan de wijsheid, om voor eeuwig koning te zijn.',
        22: 'Ik wil u verkonden, wat wijsheid is, en hoe zij ontstond; Ik wil u niet haar geheimen verbergen, Maar haar spoor volgen sinds het begin van haar wording; Ik wil haar kennis aan het licht doen treden, En in geen enkel opzicht de waarheid voorbijgaan.',
        23: 'Ik wil mij ook niet laten leiden door verterende afgunst, Want die gaat met wijsheid niet samen;',
        24: 'Maar een groot getal wijzen is de redding der wereld, En een verstandig vorst de welvaart van zijn volk.',
        25: 'Laat u dus door mijn woorden onderrichten, En gij zult er uw voordeel bij vinden.',
    },
    7: {
        1: 'Ook ik ben sterfelijk, zoals alle anderen, Een nazaat van den eerste, en die werd uit aarde gemaakt; In de schoot van een moeder werd ik tot een lichaam gevormd,',
        2: 'In de tijd van tien maanden uit geronnen bloed, Uit het zaad van een man En de lust, aan echtelijke omgang verbonden.',
        3: 'Ook ik ademde na de geboorte de gemeenschappelijke lucht, En kwam terecht op de aarde, die allen doet lijden; Ik schreide mijn eerste geluid, gelijk alle anderen,',
        4: 'Werd in windselen grootgebracht onder veel zorgen.',
        5: 'Want geen koning had ooit bij zijn geboorte een ander begin;',
        6: 'Gelijk is voor allen de aanvang en het einde van het leven.',
        7: 'Daarom heb ik gebeden: toen werd mij inzicht gegeven; Ik smeekte: en de geest van wijsheid kwam in mij.',
        8: 'Ik heb haar gesteld boven schepters en tronen; Bij haar vergeleken, telde ik rijkdom voor niets,',
        9: 'Zelfs de kostbaarste steen stelde ik niet met haar gelijk; Want alle goud is met haar vergeleken wat stof, En zilver geldt naast haar enkel als slijk.',
        10: 'Meer dan gezondheid en schoonheid had ik haar lief, En gaf haar de voorkeur boven het licht; Want de glans, die zij uitstraalt, dooft nooit.',
        11: 'Tegelijk met haar viel mij groter goed nog ten deel, Want onmetelijke rijkdom ligt in haar handen;',
        12: 'Ik genoot van dit alles, daar de wijsheid het meebracht, Zonder te weten, dat zij er de moeder van was.',
        13: 'In oprechtheid heb ik haar leren kennen, En zonder afgunst deel ik haar mee,',
        14: 'Want zij is voor de mensen een onuitputtelijke schat; Die hem benutten, verwerven Gods vriendschap, Omdat ze welgevallig worden door gaven van deugd.',
        15: 'Moge God mij dan geven, overeenkomstig mijn kennis te spreken, En gedachten te vormen, zijn gaven waardig! Hij toch is de leidsman der wijsheid, Hij toont aan de wijzen de weg;',
        16: 'Want in zijn hand zijn wij, evenals onze woorden, Alle inzicht, bekwaamheid en kunnen.',
        17: 'Ja, Hijzelf schonk mij betrouwbare kennis der dingen, Om de bouw van het heelal en de kracht der elementen te kennen:',
        18: 'Het begin, het einde en het midden der tijden, Het wenden van de zonnestand, en de wisseling van de jaargetijden,',
        19: 'De kringloop der jaren en de stand van de sterren.',
        20: 'De natuur van de dieren en de aard der wilde beesten, De macht van de geesten en de gedachten der mensen, De soorten van planten en de krachten der wortels:',
        21: 'Verborgen of zichtbaar, ik heb alles leren kennen, Want de wijsheid, die alles maakte, leerde het mij.',
        22: 'Want in haar is een geest, verstandig en heilig, Enig, veelzijdig, onstoffelijk, Vaardig, doordringend en smetteloos, Helder, onkwetsbaar, bedacht op het goede, scherp, Onweerstaanbaar, weldadig, menslievend.',
        23: 'Standvastig, betrouwbaar, zonder zorgen, Alles vermogend en alles besturend, Al de andere geesten doordringend, Hoe verstandig, rein en scherpzinnig zij ook zijn.',
        24: 'Want de wijsheid is sneller dan al wat beweegt, Zij doordringt en doortrekt alles door de kracht van haar reinheid.',
        25: 'Want zij is een ademtocht van de Majesteit Gods, Een reine uitstraling van de glorie van den Almachtige; Daarom kan niets, wat besmet is, haar raken.',
        26: 'Zij is de weerglans van het eeuwige licht, Een vlekkeloze spiegel van Gods kracht, Het beeld van zijn volmaaktheid.',
        27: 'Zij is slechts één, maar kan alles, Blijft zelf steeds dezelfde, terwijl ze alles vernieuwt; Van geslacht tot geslacht treedt zij binnen in heilige zielen, En vormt ze tot vrienden Gods en profeten.',
        28: 'Want God heeft hen alleen lief, Die met de wijsheid vertrouwd zijn.',
        29: 'Zij is schoner dan de zon en heel het leger der sterren, Met het licht vergeleken, is de voorrang aan haar; Want op het licht volgt de nacht, Maar de wijsheid wordt nooit door de boosheid verwonnen.',
    },
    8: {
        1: 'Haar kracht strekt zich uit van het ene eind tot het andere, Zij is het, die alles ten beste beschikt.',
        2: 'Ik had haar lief en zocht haar sinds mijn jeugd, Zocht haar te winnen als bruid; Want ik werd verliefd op haar schoonheid.',
        3: 'Zij roemt haar edele afkomst; Want zij leeft in gemeenschap met God, En Hij, die de Heer is van alles, bemint haar.',
        4: 'Ja, zij is ingewijd in de kennis van God, En is zijn raadsvrouw bij zijn werken.',
        5: 'Als rijkdom een begerenswaardig bezit is in het leven, Wat is er rijker dan de wijsheid, die alles bewerkt;',
        6: 'En als iemand naar scherpzinnigheid streeft, Wie ter wereld is vaardiger dan zij?',
        7: 'Heeft iemand de gerechtigheid lief, Heel haar streven is op deugden gericht; Want zij leert matigheid en voorzichtigheid, Rechtvaardigheid en sterkte; En niets bestaat er, dat nuttiger is Voor den mens in zijn leven.',
        8: 'Wanneer iemand streeft naar rijke ervaring, Zij kent het verleden en doorziet de toekomst; Zij verstaat de zin van spreuken, En de oplossing van raadsels; Wonderen en tekenen kent zij te voren Met de lotgevallen van tijden en eeuwen.',
        9: 'Ik besloot dus, haar te nemen als levensgezellin, Wetend. dat zij mij het goede zal raden, En zal troosten in zorgen en smart.',
        10: 'Door haar zal ik roem verwerven bij het volk, En eer bij de oudsten, ofschoon ik nog jong ben.',
        11: 'Bij het rechtspreken zal ik scherpzinnig zijn, En bewondering vinden in het oog van de vorsten.',
        12: 'Zwijg ik, dan zullen ze wachten, Als ik spreek, aandachtig luisteren; En al voer ik nog langer het woord, Ze leggen de hand op hun mond.',
        13: 'Door haar zal ik onsterfelijkheid verwerven, Een eeuwig aandenken achterlaten bij wie na mij komen.',
        14: 'Ik zal volkeren besturen en naties onderwerpen,',
        15: 'Gevreesde tyrannen zullen met schrik van mij horen; Bij mijn volk zal ik goed zijn, En dapper in de krijg.',
        16: 'Als ik terugkeer naar huis, bij haar vind ik rust; Want de omgang met haar heeft nimmer iets bitters, En met haar verkeren geeft nimmer verdriet, Maar vreugde en blijdschap.',
        17: 'Omdat ik dit bij mijzelf bedacht, En overwoog in mijn hart: Dat er onsterfelijkheid ligt in het gezelschap der wijsheid,',
        18: 'En edel genot in haar vriendschap, Onuitputtelijke rijkdom in het werk van haar handen, Doorzicht in de innige omgang met haar, En roem in het deelnemen aan haar gesprekken: Daarom zocht ik overal rond, hoe haar tot mij te nemen.',
        19: 'Ik was een knaap van schone gestalte, En ik had een voortreffelijke ziel ontvangen;',
        20: 'Of liever, omdat ik voortreffelijk was, Kwam ik in een lichaam zonder gebreken.',
        21: 'Maar ik begreep, haar nooit te zullen bezitten, als God ze niet gaf; En het is reeds wijsheid te weten, wiens gave zij is. Daarom wendde ik mij tot den Heer in gebed, En sprak uit het diepst van mijn hart:',
    },
    9: {
        1: 'God der vaderen, barmhartige Heer, Die door uw woord het heelal hebt geschapen,',
        2: 'En door uw wijsheid den mens hebt gevormd, Opdat hij zou heersen over uw schepping,',
        3: 'Heilig en rechtvaardig de wereld besturen, En rechtzinnig van hart zou regeren:',
        4: 'Verleen mij de wijsheid, die op uw troon is gezeten, En sluit mij niet buiten de kring uwer kinderen.',
        5: 'Ik ben toch uw dienstknecht, de zoon van uw dienstmaagd, Een mens vol zwakheid en kortstondig van leven, Die weinig begrip heeft van recht en van wetten.',
        6: 'Ja, al is iemand ook de volmaaktste der mensen, Zonder uw wijsheid geldt hij voor niets;',
        7: 'Toch hebt Gijzelf mij verkoren tot koning van uw volk, Tot vorst van uw zonen en dochters.',
        8: 'Gij liet mij een tempel bouwen op uw heilige berg, En een altaar in de stad, waar Gij woont, Als een beeld van de heilige tent, Die Gij van de aanvang af hebt bereid.',
        9: 'Bij U toch is de wijsheid, die uw werken kent, Die tegenwoordig was, toen Gij de wereld schiept; Die weet, wat behaaglijk is in uw ogen En wat recht is naar uw geboden.',
        10: 'Zend haar neer uit de heilige hemel, En doe haar uitgaan van de troon uwer glorie, Opdat zij mij ter zijde sta bij mijn werken, En ik moge weten, wat U behaagt.',
        11: 'Zij toch weet alles en begrijpt alles; Zij zal mij beleidvol bij mijn daden besturen, En mij beschermen door haar glorie.',
        12: 'Dan zullen mijn werken welbehaaglijk zijn, Zal ik uw volk rechtvaardig besturen, En de troon van mijn vader waardig zijn.',
        13: 'Want wie van de mensen zou Gods wil kunnen kennen; Wie achterhalen, wat de Heer verlangt?',
        14: 'De gedachten der stervelingen zijn immers weifelend, En onzeker onze berekeningen.',
        15: 'Want het sterfelijk lichaam is een last voor de ziel, De aardse tent belemmert de geest bij het denken;',
        16: 'Nauwelijks bevroeden wij de dingen der aarde, Zelfs wat voor de hand ligt, verstaan wij met moeite. Wie zal dan de dingen des hemels doorgronden,',
        17: 'Wie uw wil kunnen kennen, Als Gij geen wijsheid zoudt schenken, Niet van boven uw heilige geest zoudt zenden?',
        18: 'Zo alleen vinden de bewoners der aarde rechte paden, Leren de mensen wat U welgevallig is, En worden zij gered door de wijsheid.',
    },
    10: {
        1: 'Zij heeft den eerstgeschapen vader der wereld Reeds bescherming verleend, toen hij nog alleen was. Ook uit zijn zondeval heeft zij hem gered,',
        2: 'En hem de kracht geschonken, om over alles te heersen.',
        3: 'Maar toen een ongerechte in zijn toorn van haar afviel, Kwam hij om door de woede, waarin hij zijn broeder doodde.',
        4: 'En toen om hem de vloed kwam over de aarde, Bracht de wijsheid weer redding, En loodste den rechtvaardige op nietig hout er doorheen.',
        5: 'Nadat de volken verspreid waren om de algemene boosheid, Vond zij den gerechte, bewaarde hem voor God zonder smet, En deed hem standvastig blijven, ondanks de liefde voor zijn kind.',
        6: 'Zij redde den rechtvaardige, bij de ondergang der zondaars, Toen hij het vuur ontvluchtte, dat op de vijf steden neerkwam.',
        7: 'Daar bevindt zich nog altijd als teken der boosheid Een altijd dampende woestenij, Met planten, die op verkeerde tijden vruchten dragen, En een hoge zoutzuil als herinnering aan een ongelovige vrouw.',
        8: 'Want zij, die de weg der wijsheid hadden verlaten, Verloren niet alleen de kennis van het goede, Maar lieten de wereld ook een herinnering na aan hun dwaasheid, Opdat niet verborgen zou blijven, wat zij hebben misdreven.',
        9: 'Maar wie de wijsheid dienden, heeft zij uit kwelling gered.',
        10: 'Toen de rechtvaardige vluchtte voor de toorn van zijn broeder, Heeft zij hem langs veilige wegen geleid; Zij heeft hem het rijk van God laten zien, En hem kennis van het heilige geschonken. Zij maakte hem rijk bij zijn moeitevol werk, En schonk hem overvloedige vrucht van zijn arbeid;',
        11: 'Zij stond hem ter zijde tegen de hebzucht van zijn verdrukkers, Zij was het, die hem rijkdom schonk.',
        12: 'Zij beschermde hem tegen zijn vijanden, En beschutte hem tegen zijn belagers; Bij een felle strijd schonk zij hem de overwinning, Opdat hij zou weten, dat vroomheid alles in kracht overtreft.',
        13: 'Zij liet den rechtvaardige, die verkocht was, niet in de steek, Maar bewaarde hem voor de zonde; Zij daalde met hem in de kerker af,',
        14: 'En liet hem in zijn boeien niet alleen. Ja, zij verschafte hem een koningsschepter En macht over hen, die eerst hem verdrukten; Zij bewees, dat zijn aanklagers leugenaars waren, En verleende hem eeuwige roem.',
        15: 'Zij heeft een heilige natie, een geslacht zonder smet, Bevrijd van het volk der verdrukkers;',
        16: 'Zij ging binnen in de ziel van den dienaar des Heren, En weerstond schrikwekkende vorsten met tekenen en wonderen.',
        17: "Zij verschafte de heiligen het loon voor hun zwoegen, En geleidde hen langs een wondere weg; Overdag werd zij voor hen een beschutting, En 's nachts als het licht van de sterren.",
        18: 'Zij voerde hen door de Rode Zee En geleidde hen over het grote water;',
        19: 'Maar hun vijanden liet zij verdrinken, En spoelde uit de diepte der zee hen weer aan. Zo hebben de rechtvaardigen de zondaars geplunderd.',
        20: 'Zij bezongen, o Heer, uw heilige Naam, En prezen eenstemmig uw hand, die hier streed;',
        21: 'Want de wijsheid opende de mond van de stommen, En maakte de tong van de kleinen welsprekend.',
    },
    11: {
        1: 'Zij liet hun ondernemingen slagen Onder leiding van een heilig profeet.',
        2: 'Ze trokken door een onbewoonbare steppe, En richtten hun tenten op in onbegaanbare oorden;',
        3: 'Ze boden weerstand tegen hun vijanden, En sloegen hun tegenstanders af.',
        4: 'Als ze dorst hadden, riepen ze tot U; En uit een steile rots ontvingen ze water, En lessing van hun dorst uit harde steen.',
        5: 'Ja, hetzelfde, dat hun vijanden als straf overkwam Werd hùn een zegen in hun nood.',
        6: 'Want terwijl de altijdstromende bron van de Nijl Door walgelijk bloed werd vertroebeld,',
        7: 'Tot straf voor hun bevel, om de kinderen te doden, Gaaft Gij hùn onverhoopt rijkelijk water.',
        8: 'Maar door hun eigen dorst hebt Gij hun getoond, Hoe Gij hun vijanden eens hadt gestraft;',
        9: 'Want door die beproeving, die een liefdevolle terechtwijzing was, Begrepen zij de kwelling der bozen, die in toorn werden gestraft.',
        10: 'Hen toch hebt Gij als een waarschuwend vader beproefd, Maar de anderen als een streng vorst gericht en gestraft.',
        11: 'Hun kwelling bleef na het vertrek der eersten even groot als tevoren;',
        12: 'Ja, een dubbele smart greep hen aan: Hun zuchten bij de herinnering aan het verleden.',
        13: 'Toen ze immers vernamen, dat hun eigen plagen Voor de eersten in weldaad verkeerden, erkenden ze de hand des Heren.',
        14: 'Want dien ze te vondeling hadden gelegd en spottend afgewezen, Moesten ze ten slotte bewondering schenken, Daar ze zelf een heel andere dorst leden dan de rechtvaardigen.',
        15: 'Omdat ze, door hun dwaze, goddeloze gedachten misleid, Redeloos gedierte en nietige insecten vereerden, Hebt Gij hun een menigte redeloze dieren gezonden als straf,',
        16: 'Om hun te leren, dat men gestraft wordt in hetgeen men misdoet.',
        17: 'Want het was niet moeilijk geweest voor uw almachtige hand, Die toch de aarde gemaakt heeft uit vormloze stof, Hun een menigte beren te zenden of grimmige leeuwen,',
        18: 'Of nieuw-geschapen, ongekende, woedende beesten. Beesten, die gloeiende adem uitsnuiven of sissende wolken rook, Of die vreselijke vonken uit de ogen schieten;',
        19: 'Die niet slechts door hun geweld hen hadden kunnen verdelgen, Maar wier aanblik alleen hen van schrik had doen sterven.',
        20: 'Ook zonder dat hadden ze door één windstoot kunnen vallen, Door uw wraakgericht achtervolgd, En voortgejaagd door uw machtige adem; Maar Gij hebt alles geordend naar maat, getal en gewicht.',
        21: 'Zeker, Gij kunt overal uw grote macht ontplooien; Wie zou er kunnen weerstaan aan de kracht van uw arm?',
        22: "Want heel de aarde is voor U als een stofje op de weegschaal, Als een dauwdruppel, die 's morgens neervalt op het land.",
        23: 'Maar Gij ontfermt U over allen, omdat Gij alles vermoogt; Gij let niet op de zonden der mensen, opdat zij zich bekeren.',
        24: 'Want Gij omsluit in uw liefde alles wat er bestaat, En verafschuwt niets van wat Gij gemaakt hebt. Ja, als Gij iets haat, hadt Gij het niet geschapen.',
        25: 'Hoe zou iets kunnen bestaan, als Gij het niet wilt; Of iets kunnen standhouden, als Gij het niet roept?',
        26: 'Maar Gij spaart alles, omdat het van U is, Gij, minnaar van al wat leeft, o Heer!',
    },
    12: {
        1: 'Want uw onsterfelijke geest is in alles,',
        2: 'En daarom straft Gij de zondaars slechts matig; Gij houdt hun door die waarschuwing hun misdaad voor ogen, Opdat zij de zonde verlaten en U trouw blijven, Heer.',
        3: 'Ook de vroegere bewoners van uw heilig land',
        4: 'Hebt Gij gehaat om hun schandelijk leven,',
        5: 'Om hun toverkunst en afschuwelijke gebruiken: Het meedogenloos moorden van kinderen, Het eten van ingewanden, en vlees en bloed van mensen. Daarom hebt Gij die ingewijden uit hun festijnen weggerukt,',
        6: 'En de ouders, die eigenhandig hun arme kinderen doodden, Door de hand van onze vaderen willen verdelgen:',
        7: 'Opdat het land, dat door U het hoogst wordt geschat, Een waardige bevolking zou opnemen van kinderen Gods.',
        8: 'Toch hebt Gij ook hen, als mensen, genadig behandeld, En als voorlopers van uw leger horzels gezonden, Om hen slechts langzaam uit te roeien;',
        9: 'Al hadt Gij de zondaars in de krijg aan de gerechten kunnen overleveren, Of in eens verdelgen door grimmige dieren of een streng bevel.',
        10: 'Door niet in eens te straffen gaaft Gij hun tijd tot bekering, Ofschoon Gij wist, dat hun geslacht was bedorven, Dat de boosheid hun was aangeboren, En dat hun gezindheid in eeuwigheid niet zou veranderen,',
        11: 'Daar hun zaad was vervloekt van de aanvang af. Niet uit ontzag voor iemand gaaft Gij uitstel aan hun zondestraf;',
        12: 'Want wie zal durven zeggen: “Wat doet Gij?” Of wie zal zich verzetten tegen uw oordeel? Wie klaagt U aan, als Gij volken verdelgt, die Gij zelf hebt geschapen; Of wie treedt er tegen U op als verdediger van zondige mensen?',
        13: 'Er is geen God buiten U, die zorg draagt voor allen, En zo bewijst, dat Gij niet onrechtvaardig straft.',
        14: 'Geen koning of vorst kan U rekenschap vragen over wien Gij kastijdt;',
        15: 'Maar omdat Gij rechtvaardig zijt, ordent Gij alles rechtvaardig. Wie geen straf verdient, straffen, Acht Gij in strijd met uw macht.',
        16: 'Want uw macht is de grond van uw rechtvaardigheid; En juist wijl Gij alles beheerst, wordt door U alles gespaard.',
        17: 'Want Gij toont uw kracht slechts, als men uw almacht uitdaagt; Gij straft enkel wie ze kent, en toch overmoedig is.',
        18: 'Maar hoe groot ook uw kracht is, Gij straft met zachtheid, En heerst over ons met grote toegevendheid; Want als Gij maar wilt, het kunnen ligt in uw macht.',
        19: 'Maar Gij hebt door zo te handelen uw volk willen leren, Dat menslievendheid een plicht is voor den rechtvaardige; En Gij hebt aan uw zonen de blijde hoop gegeven, Dat Gij na de zonden bekering schenkt.',
        20: 'Want als Gij de vijanden uwer kinderen, die de dood verdienden, Zo behoedzaam en omzichtig gestraft hebt, Tijd en gelegenheid gegeven, om zich van het kwaad te bekeren:',
        21: 'Met welk een omzichtigheid zult Gij dan uw kinderen richten, Wier vaderen Gij onder eed en verbond de heerlijkste beloften hebt gegeven!',
        22: 'Ons wijst Gij terecht, onze vijanden geselt Gij duizendmaal, Opdat wij, als wij straffen, aan uw goedheid zouden denken, En als wij gestraft worden, op barmhartigheid hopen.',
        23: 'Daarom ook hebt Gij de bozen, die in dwaasheid hun leven vergooiden, Door hun eigen gruwelen gefolterd.',
        24: 'Want ze waren op de ergste doolwegen afgedwaald, Door de meest verachte en afschuwelijke beesten als god te beschouwen, En zo zichzelf te misleiden als onnozele kinderen.',
        25: 'Daarom hebt Gij hun, als kinderen zonder verstand, Een straf gezonden, die hen bespottelijk maakte.',
        26: 'Maar wie na een kastijding met spot zich niet betert, Zal een straf ondergaan, die God waardig is.',
        27: 'Want in hun lijden, toen ze zich enkel maar ergerden Over hun waangoden, waarmee ze werden gekweld, Hadden ze den waren God moeten vinden, dien ze vroeger miskenden: Daarom kwam de allerzwaarste straf over hen.',
    },
    13: {
        1: 'Want grote dwazen zijn alle mensen, die God niet kennen: Die niet door de zichtbare goederen heen Hem vermogen te zien, Wel zijn werken aanschouwen, maar den Schepper niet vinden;',
        2: 'Maar die het vuur of de wind of de vluchtige lucht, Of de kring van de sterren of het geweldige water, Of de luchters des hemels aanzien als goden, die de wereld besturen.',
        3: 'Als zij door hun schoonheid bekoord, ze als god beschouwden, Hadden zij moeten begrijpen, dat hun Meester heerlijker is; Want de Maker van alle schoonheid heeft ze geschapen.',
        4: 'En als hun macht en werking ze in bewondering bracht, Hadden zij moeten inzien, dat hun Schepper veel machtiger is.',
        5: 'Want uit de grootheid en schoonheid der schepselen Kent men door vergelijking den Schepper.',
        6: 'Toch zijn dezen nog minder te laken: Want zij dwalen wel, maar zoeken toch God en willen Hem vinden;',
        7: 'Zij onderzoeken tenminste zijn werken en vorsen ze na, Maar worden misleid door de schijn van hun uiterlijke pracht.',
        8: 'Van de andere kant zijn ook zij niet geheel zonder schuld:',
        9: 'Want als zij hun kennis zo ver konden brengen, Dat zij in staat waren, het heelal te doorvorsen, Waarom hebben zij dan niet veeleer den Heer van dat alles gevonden?',
        10: 'Maar werkelijk rampzalig zijn zij, die op doden vertrouwen, Doordat zij het werk van mensenhanden beschouwen als god: Goud en zilver, kunstproducten en dierenbeelden, Of waardeloze steen, oudtijds door mensenhanden bewerkt;',
        11: 'Of een stevige boom, die een houtbewerker omzaagt, En geheel in het rond zorgvuldig van zijn schors ontdoet, Die hij keurig bewerkt en tot een meubel maakt, Dat het gemak des levens kan dienen.',
        12: 'Wat er afvalt bij het werk, benut hij om zijn maal te bereiden, En zo zijn buik te vullen.',
        13: 'Blijft er dan nog wat over, dat nergens voor dient, Een krom stuk hout, met knoesten doorgroeid, Dan gaat hij het bewerken voor tijdverdrijf, En geeft er handig een vorm aan voor zijn ontspanning: Hij geeft het de gedaante van een mens,',
        14: 'Of de gestalte van een armzalig beest. Dan smeert hij er wat menie op, en kleurt het van buiten rood; En wat voor vlekken het heeft, ze worden met verf bedekt.',
        15: 'Dan maakt hij er een passend voetstuk onder, En hangt het aan de wand met een spijker vast;',
        16: 'Zo zorgt hij er voor, dat het niet kan vallen. Want hij weet wel, dat het zich niet zelf kan redden: Het is maar een beeld, dat hulp behoeft.',
        17: 'Maar als hij voor zijn bezit, voor vrouw en kinderen wil bidden, Schaamt hij zich niet, tot het levenloze ding te gaan spreken: Om gezondheid bidt hij het zwakke,',
        18: 'Om leven vraagt hij het dode; Om bijstand smeekt hij het machteloze, Om een voorspoedige reis, wat geen voet kan verzetten;',
        19: 'Voor winst en arbeid en succes bij het werk Vraagt hij kracht aan wat zijn eigen hand niet kan roeren.',
    },
    14: {
        1: 'Weer een ander, die een zeereis begint, En de wilde golven gaat doorklieven, Roept een hout aan, dat veel brozer is Dan het vaartuig, dat hem draagt.',
        2: 'Want hieraan werd door winzucht de nodige zorg besteed, En met vakkundig inzicht werd het gebouwd.',
        3: 'En het is uw Voorzienigheid, o Vader, die het bestuurt; Want Gij baant ook op zee een weg, Een veilig pad te midden der golven.',
        4: 'Gij toont daardoor, dat Gij in staat zijt, uit alles te redden, Zodat men ook zonder stuurmanskunst zee zou durven kiezen.',
        5: 'Maar daar Gij de werken uwer wijsheid niet onbenut wilt laten, Vertrouwen de mensen hun leven toe aan een klein stuk hout, En varen op een scheepje behouden door de branding.',
        6: 'Ook in de oude tijd, bij de ondergang der trotse reuzen, Ontkwam de hoop der wereld op een schip; En door uw hand bestuurd, bewaarde hij voor de wereld Het zaad voor een nageslacht.',
        7: 'Want gezegend is het hout, dat tot gerechtigheid dient.',
        8: 'Maar vervloekt het beeld, door mensenhand gemaakt, tegelijk met zijn maker: Deze, omdat hij het heeft gemaakt; Het vergankelijk beeld, omdat het god wordt genoemd.',
        9: 'Want de goddeloze is bij God gehaat met zijn goddeloos werk;',
        10: 'En het maaksel wordt gestraft tegelijk met hem, die het maakte.',
        11: 'Ja, ook over de beelden der heidenen komt het gericht, Omdat zij een gruwel werden onder de schepselen Gods, Een ergernis voor de zielen der mensen, En een valstrik voor de voeten der dwazen.',
        12: 'Want de gedachte aan beelden was het begin van de afval, Het uitvinden ervan werd het bederf des levens.',
        13: 'Ze bestonden niet van de aanvang af, En zullen niet eeuwig blijven;',
        14: 'Want door de ijdele waan der mensen kwamen ze in de wereld, En daarom is hun een spoedig einde beschoren.',
        15: 'Een vader toch, verteerd door onverwachte smart, Maakte een beeld van zijn kind, te vroeg hem ontrukt; Die als mens was gestorven, vereerde hij nu als god, En stelde voor zijn ondergeschikten een plechtige eredienst in.',
        16: 'Toen die slechte gewoonte zich mettertijd had verbreid,',
        17: 'Gold zij als wet, en vereerde men beelden op bevel der vorsten. Want als men om de verre afstand henzelf niet kon vereren, Maakte men zich uit de verte een voorstelling van hun gestalte. Men vervaardigde een prachtig beeld van den gevierden koning, Om met alle ijver den afwezige te vleien, als was hij er bij;',
        18: 'En de eerzucht van den kunstenaar bewoog zelfs wie den koning niet kenden. Om diens verering nog te vergroten.',
        19: 'Want om den vorst te behagen, gaf hij zich alle moeite, Om door zijn kunst het beeld zo schoon mogelijk te maken;',
        20: 'En het volk, misleid door de schoonheid van het werk, Aanbad, dien men te voren als mens eerde, voortaan als god.',
        21: 'En dit is voor de mensen een valstrik geworden: Dat zij door ongeluk gedreven of om vorsten te vleien, Aan hout of steen de Naam gaven, die slechts toekomt aan Eén.',
        22: 'Maar, zij dwalen niet alleen in de kennis van God! Neen, terwijl zij door hun onkunde leven in grote strijd, Begroeten zij zulk een ellende nog als vrede.',
        23: 'Want zij offeren hun kinderen, vieren verborgen geheimen, Of dolle feestgelagen met vreemde gebruiken,',
        24: 'En verwaarlozen de reinheid van leven en huwelijk. De een vermoordt den ander of krenkt hem door echtbreuk;',
        25: 'Overal heerst zonder onderscheid moord en doodslag, Diefstal, bedrog en verleiding, onbetrouwbaarheid, oproer en meineed;',
        26: 'Vervolging der goeden, ondank voor weldaden, Verpesting der zielen, onkuisheid tegen de natuur, Verwording van het huwelijk, echtbreuk en ontucht.',
        27: 'Want de verering der verfoeilijke afgoden Is het begin, de oorzaak en het einde van alle kwaad.',
        28: 'Ja, zij vieren hun dolle feesten en profeteren leugens, Leven losbandig en doen valse eden zonder wroeging;',
        29: 'Want zij stellen hun vertrouwen op levenloze goden, En verwachten daarom geen straf voor hun meineed.',
        30: 'Maar een rechtvaardige straf treft hen voor dit dubbel vergrijp: Dat zij goden vereren, maar kwaad denken van God; En door meineed en bedrog de deugd vertreden.',
        31: 'Ja, al bezitten zij, bij wie men zweert, ook geen macht, Toch volgt de straf der zonde steeds op het misdrijf der bozen.',
    },
    15: {
        1: 'Maar Gij, onze God, zijt goedertieren en trouw; Lankmoedig en vol ontferming bestuurt Gij het heelal.',
        2: 'Wij zijn van U; zondigen wij ook, wij erkennen uw macht! Maar wij willen niet zondigen, wetende, dat wij U toebehoren!',
        3: 'Want U kennen is volmaakte gerechtigheid, Uw macht beseffen de wortel der onsterfelijkheid.',
        4: 'Neen, ons heeft geen bedriegelijk uitvindsel van mensen misleid, Noch de nutteloze arbeid van schilders; Geen beeld met bonte kleuren besmeerd,',
        5: 'Dat door zijn aanblik den dwaas verleidt, Om de dode gestalte te minnen van een levenloos beeld.',
        6: 'Minnaars der boosheid en waard op zo iets te hopen Zijn zij, die ze maken, en die ze liefde en eerbied betonen.',
        7: 'Een pottebakker bijvoorbeeld kneedt moeizaam de weke klei, En vormt ten onzen gerieve allerlei vaten. Uit hetzelfde leem vormt hij zonder verschil De vaten, die dienen voor een eerzaam gebruik, Maar ook, die voor iets anders bedoeld zijn; En welke bestemming elk van beide zal vinden, Het is de pottebakker, die het beslist.',
        8: 'Met onzalige ijver maakt hij uit dezelfde klei een nietigen god: Hij, die kort geleden zelf uit aarde ontstond, En binnenkort terugkeert naar haar, waaruit hij werd genomen, Als de ziel, die hij te leen kreeg, wordt teruggevorderd.',
        9: 'Maar hij denkt er niet aan, dat hij eens zal verdwijnen, En dat hij een kortstondig leven heeft. Neen, hij wil zich met goud- en zilversmeden meten, Bootst den koperslager na, En gaat er nog groot op, dat hij namaak levert.',
        10: 'Zijn hart is enkel as, Nietiger nog dan zand zijn hoop; Zijn leven is nog minder waard dan het leem.',
        11: 'Want hij miskent Hem, die hem maakte, Die hem een werkzame geest inblies, En een levende ziel in hem plantte.',
        12: 'Ja, hij beschouwt ons leven als een spel, Ons bestaan als een winstgevende kermis; Uit alles, zelfs uit het kwaad, meent hij voordeel te moeten trekken.',
        13: 'Toch weet hij beter nog dan anderen, dat hij zondigt, Als hij uit stof der aarde broze potten en beelden maakt.',
        14: 'Grote dwazen zijn zij allen, erger nog dan een kind, De vijanden van uw volk, die het hebben verdrukt.',
        15: 'Want alle goden der heidenen houden zij voor god, Ofschoon die hun ogen niet kunnen gebruiken, om te zien, Hun neus niet, om lucht in te ademen, Hun oren niet, om te horen, De vingers van hun handen niet, om te tasten, En wier voeten niet in staat zijn, om te gaan.',
        16: 'Want het is een mens, die ze heeft gemaakt; Eén, die zelf de geest in leen kreeg, heeft ze gevormd. Ja, een mens vermag niet eens, een god te maken, aan zich gelijk:',
        17: 'Zelf sterfelijk, maakt hij met snode handen een levenloos ding; Maar zelf is hij beter, dan dat wat hij aanbidt, Want hij bezit het leven, dat andere niet!',
        18: 'Zelfs vereren zij de afschuwelijkste beesten, Die door hun domheid nog lager staan dan de anderen,',
        19: 'Die niet mooi genoeg zijn, om er van te houden, Zoals dat bij het zien van dieren mogelijk is: Maar aan wie Gods lofspraak en zegen zijn ontgaan.',
    },
    16: {
        1: 'Daarom werden zij door zulke dieren naar verdienste gestraft, En door een menigte ongedierte gekweld;',
        2: 'Maar in plaats van die straf deedt Gij goed aan uw volk: Toen Gij als ongewone spijs voor hun gretige honger Hun de kwartel als voedsel hebt bezorgd.',
        3: 'Want als de anderen begeerden te eten, Moest door de afschuw voor hetgeen op hen neerkwam Zelfs de natuurlijke honger vergaan; Terwijl dezen na een kortstondig gebrek Zelfs een wonderbaar voedsel ontvingen.',
        4: 'Voor die verdrukkers moest onvermijdelijk gebrek ontstaan, Maar hùn werd enkel getoond, hoe hun vijanden werden bestraft.',
        5: 'Ja, toen hèn de grimmige woede van dieren overviel, En zij door de beet van kronkelende slangen vergingen, Bleef uw toorn toch niet eindeloos duren.',
        6: 'Zij werden ter waarschuwing een tijdlang verschrikt, Maar ontvingen een reddend symbool, Om aan de geboden van uw wet te worden herinnerd.',
        7: 'Want wie er naar keek, werd niet gered door wat hij zag, Maar door U, den Redder van allen;',
        8: 'En daardoor hebt Gij onze vijanden bewezen, Dat Gij het zijt, die uit alle nood bevrijdt.',
        9: 'Want de anderen werden gedood door de beet van sprinkhaan en vlieg, En voor hèn werd geen genezing gevonden, Omdat ze verdiend hadden, zó te worden gestraft.',
        10: 'Maar uw kinderen kon de tand van giftige slangen niet deren; Want uw ontferming kwam tussenbeiden, om hen te genezen.',
        11: 'Al werden zij gestoken, om ze te herinneren aan uw geboden, Toch werden zij terstond weer gered, Opdat zij niet uw geboden geheel en al zouden vergeten, En niet van uw goedheid zouden worden verstoken.',
        12: 'Neen, geen kruid was het, geen pleister, die hen genas, Maar uw woord, Heer, dat alles geneest;',
        13: 'Gij toch hebt macht over leven en dood, Gij voert naar de poorten van het dodenrijk af, en brengt weer omhoog.',
        14: 'Een mens daarentegen kan in zijn boosheid wel doden, Maar de geest, die ontvlood, niet doen keren, En geen buitgemaakte ziel weer bevrijden.',
        15: 'Onmogelijk is het, uw hand te ontvluchten!',
        16: 'Want de goddelozen, die weigerden, U te erkennen, Werden door de kracht van uw arm getuchtigd, Door hevige regen en hagel en verschrikkelijk onweer vervolgd, Of door het vuur van de bliksem verteerd. Ja, nog wonderlijker: in het alles blussende water Woedde het vuur met ongewone kracht. Ja, de schepping strijdt voor de rechtvaardigen!',
        18: 'Want nu eens werd het vuur getemperd, Om het ongedierte niet te verbranden, Dat was losgelaten op de zondaars, Opdat ze heel duidelijk zouden begrijpen, Dat ze door Gods oordeel werden vervolgd;',
        19: 'Dan weer brandde het, midden in water boven zijn kracht, Om de gewassen van het zondige land te vernielen. Uw volk daarentegen hebt Gij met Engelenspijze gevoed,',
        20: 'En zonder moeite toebereid brood uit de hemel gezonden, Dat alle geneugten bood en ieders smaak voldeed.',
        21: 'Want uw gave openbaarde uw goedheid jegens uw kinderen, Doordat zij de begeerte voldeed van wie ze genoot, En veranderde in wat men verlangde.',
        22: 'Sneeuw en ijs weerstonden het vuur en smolten niet, Opdat men zou begrijpen, dat de oogst der vijanden werd verteerd Door het vuur, dat in de hagel vlamde, En in de stortbuien heen en weer flitste;',
        23: 'Terwijl het van de andere kant zijn eigen kracht vergat, Opdat de rechtvaardigen voedsel zouden hebben.',
        24: 'Want de natuur is onderdanig aan U, die haar schiep; Zij spant zich in tot bestraffing der zondaars, Maar matigt zich, om wel te doen aan wie zich verlaten op U.',
        25: 'Daarom heeft zij ook toen zich in alles geplooid, Uw alvoedende gave gediend, zoals de gebruikers het wensten:',
        26: 'Opdat uw zonen, die Gij liefhadt, Heer, zouden leren, Dat niet de soorten van vruchten de mensen voeden, Maar dat uw woord onderhoudt, wie op U betrouwt.',
        27: 'Want ofschoon het door het vuur niet kon worden verteerd, Smolt het bij de warmte van een vluchtige zonnestraal weg.',
        28: 'Zo moest men inzien, dat men U vóór zonsopgang moet danken, En vóór de komst van het licht voor U moet verschijnen.',
        29: 'Want de hoop van ondankbaren smelt als rijp in de winter, Stroomt weg als water, dat nergens toe dient.',
    },
    17: {
        1: 'Ja, groot zijn uw gerichten, en niet te doorgronden; Daarom vervielen die kortzichtige mensen in dwaling.',
        2: 'Want die goddelozen meenden, het heilige volk te verdrukken; Maar in duisternis gebonden, in lange nacht gekluisterd, Lagen ze onder eigen dak gevangen, Verstoken van de eeuwige Voorzienigheid.',
        3: 'Want terwijl ze zich verborgen waanden met hun heimelijke zonden. Onder een donkere sluier van vergetelheid, Werden ze uiteengejaagd en hevig beangstigd, Door allerlei schrikbeelden ontsteld;',
        4: 'De schuilhoek, die hen verborg, behoedde hen niet voor vrees, Maar angstige geluiden drongen van alle kant tot hen door, En sombere spoken doemden op met trieste gezichten.',
        5: 'Geen vuur had kracht genoeg, om licht te geven; Zelfs de sterren met haar helder geflikker Konden die sombere nacht niet verlichten.',
        6: 'Slechts een vuur, dat van zelf ontstond, gaf hun af en toe licht; Dan schrokken zij op, maar als dat licht weer verdween, Leek hun, wat zij hadden gezien, nog erger.',
        7: 'Daar lagen nu de listen van hun toverkunst; Het pochen op hun kennis liep uit op schande.',
        8: 'Want zij, die angst en vrees uit zieken beloofden te bannen, Waren nu zelf ziek van belachelijke angst.',
        9: 'Want als er niets angstigs was, dat hen verschrikte, Dan werden ze opgejaagd door het kruipen van wormen Of het sissen van slangen, en stierven van angst, En durfden niet kijken naar de lucht, die men nergens ontloopt.',
        10: 'Want de boosheid toont zich laf en veroordeelt zichzelf; Altijd ducht ze gevaren, door het eigen geweten gekweld.',
        11: 'Vrees toch is niets anders dan het prijsgeven Van de hulpmiddelen, die het overleg ons kan bieden.',
        12: 'En al is soms inwendig de angst niet zo groot, Men voelt hem erger, als men de oorzaak der kwelling niet kent.',
        13: 'Anderen weer, die in de werkelijk ondragelijke nacht, Welke uit de boezem van de ondragelijke hel was ontglipt, In hun gewone sluimer lagen gedompeld,',
        14: 'Werden ofwel door wonderlijke beelden gepijnigd, Of door vertwijfeling verlamd, Of door een plotselinge en onverwachte angst overvallen.',
        15: 'Zo zonk toen iedereen neer, waar hij was, Gevangen en opgesloten in een kerker zonder boeien.',
        16: 'Want of hij landman was of herder, Of werkman, zwoegend in de eenzaamheid: Onverhoeds werd hij door de onafwendbare ramp overvallen; Door dezelfde boeien van duisternis werden allen gekneveld.',
        17: 'En was het nu het suizen van de wind, Of het zoet gekweel van vogels op lommerrijke takken, Of het bruisen van onstuimig stromend water, Of het donderend geraas van neervallende stenen,',
        18: 'Of het onzichtbare lopen van huppelende dieren, Of het luid gehuil van brullende wilde beesten, Of een echo, die weerkaatste tegen de helling der bergen: Het sloeg ze lam van schrik.',
        19: 'Want terwijl heel de wereld straalde in helder licht, En ongestoord zich bezighield met allerlei werk,',
        20: 'Lag over hen alleen een donkere nacht gespreid: Een beeld der duisternis, die hen eens zal opnemen. Toch hadden ze meer last van zichzelf dan van de duisternis.',
    },
    18: {
        1: 'Maar voor uw heiligen was het volop licht! En toen de anderen hun stem vernamen, zonder hen zelf te zien, Prezen ze hen gelukkig, ondanks hun lijden van vroeger;',
        2: 'Ze waren verheugd, dat men het geleden onrecht niet wreekte, En vroegen vergiffenis voor hun vroegere vijandschap.',
        3: 'Gij gaaft hùn daarentegen een vurige zuil, Als gids voor de onbekende tocht, En als een onschadelijke zon voor de roemvolle reis.',
        4: 'Want de anderen hadden verdiend, van het licht te worden beroofd, En in duisternis gevangen te blijven, Omdat ze uw kinderen in boeien hadden geklonken, Door wie het onvergankelijk licht van de Wet Aan de wereld moest worden geschonken.',
        5: 'Ze hadden besloten, de kinderen der heiligen te doden; Maar één kind werd te vondeling gelegd en gered. Gij hebt hen, tot straf, van een menigte kinderen beroofd, En ze allen tezamen in het bruisende water verdelgd.',
        6: 'Aan onze vaderen was die nacht tevoren aangekondigd, Opdat zij wel zouden weten, op welke eed zij hadden vertrouwd, En vol goede moed zouden zijn.',
        7: 'Zo werd de redding van de rechtvaardigen En de ondergang van den vijand door uw volk verwacht.',
        8: 'Ja, door de straf, die Gij over uw tegenstanders deedt komen, Hebt Gij òns geroepen en verheerlijkt.',
        9: 'Want terwijl de heilige kinderen der vromen heimelijk offerden, Stelden zij eensgezind vast als goddelijke wet, Dat de heiligen gelijkelijk geluk en gevaar zouden delen, En hieven zij reeds het loflied der vaderen aan.',
        10: 'Maar daar klonk als een wanklank het geklaag van den vijand, En weergalmde hun geschrei om het betreurde kind!',
        11: 'Knecht en heer werden getroffen door dezelfde straf, Onderdaan en vorst droegen hetzelfde leed;',
        12: 'Allen zonder onderscheid, en door een en dezelfde dood, Hadden lijken zonder tal. Ja, de levenden waren niet toereikend, om ze te begraven, Daar het edelste van hun kroost door één slag was verdelgd;',
        13: 'En die om hun toverkunsten bij alles ongelovig waren gebleven, Moesten bij de dood der eerstgeborenen erkennen, Dat dit volk de zoon was van God!',
        14: 'Want terwijl een diepe stilte alles omgaf, En de nacht was voortgeijld tot de helft van zijn baan,',
        15: 'Sprong uw alvermogend woord van uw koningstroon in de hemel Als een grimmig krijgsman midden in het land van verderf,',
        16: 'En droeg als een scherpe degen uw onherroepelijk bevel. Daar stond het; overal verspreidde het de dood, En terwijl het over de aarde schreed, reikte het tot de hemel.',
        17: 'Toen werden ze plotseling door vreselijke dromen verschrikt; Onverwachte angsten stortten zich over hen uit.',
        18: 'Hier viel de een half dood neer, daar de ander, En deed de oorzaak van zijn sterven nog kennen:',
        19: 'Want de dromen, die hen verschrikten, Hadden het hun gemeld, Opdat ze de dood niet zouden vinden, Zonder te weten, waarom dat onheil hen trof.',
        20: 'Zeker, ook over de gerechten kwam de beproeving des doods, Een slachting onder het volk in de woestijn; Maar toen duurde uw gramschap niet lang.',
        21: 'Want snel sprong een onberispelijk man voor hen in de bres, Met het wapen, aan zijn ambt verbonden: Gebed en verzoenend wierookoffer. Hij weerstond de toorn, maakte een einde aan de plaag, En toonde, dat hij uw dienaar was.',
        22: 'Het was niet door lichaamskracht, dat hij de toorn bedwong, Noch door geweld van wapenen; Maar door zijn woord hield hij den bestraffer tegen, Door te herinneren aan de eed en het verbond met de vaderen.',
        23: 'Want toen de lijken reeds bij hopen op elkander lagen, Trad hij er tussen, weerde de gramschap af, En versperde haar de weg naar hen, die nog leefden;',
        24: 'Want hij droeg heel de wereld op zijn opperkleed; Op vier rijen stenen stond de roem der vaderen gegrift, En op de diadeem van zijn hoofd uw Majesteit',
    },
    19: {
        1: 'Maar tegen de goddelozen woedde de gramschap Meedogenloos ten einde toe. Want Hij wist reeds tevoren, hoe ze zich zouden gedragen:',
        2: 'Hoe ze hun eerst zouden toestaan, weg te trekken, Zelfs zouden aandringen, heen te gaan, Maar dan, door spijt gedreven, hen zouden vervolgen.',
        3: 'Ja, nog waren ze bezig met rouwbetoon, Nog klaagden ze hun leed aan het graf van hun doden, Of ze namen reeds een ander, een dwaas besluit, En gingen als vluchtelingen achtervolgen, Die zij hadden gesmeekt om heen te gaan.',
        4: 'Want een welverdiend noodlot dreef hen tot dit uiterste, En deed hen vergeten, wat er gebeurd was: Zij moesten de straf ten volle ondergaan, Die nog aan hun kwelling ontbrak;',
        5: 'Maar uw volk moest een wondere doortocht bekomen, Terwijl de anderen een ongewone dood zouden vinden.',
        6: 'Want heel de schepping werd in haar natuur hervormd, Om dienstbaar te zijn aan uw bevelen, Opdat uw kinderen zonder letsel zouden worden behouden.',
        7: 'De wolk overschaduwde hun legerplaats, Droog land zag men oprijzen, waar vroeger water was: Een heerbaan zonder hindernis door de Rode Zee, Een groenend veld uit de geweldige vloed!',
        8: 'Heel het volk trok er doorheen, Beschermd door uw hand, En aanschouwde vol verbazing uw wonderen.',
        9: 'Want zij waren als paarden, die ter weide gaan, Als huppelende lammeren, En loofden U, Heer, die hen had gered.',
        10: 'Zo dachten zij terug aan wat in het vreemde land was gebeurd: Hoe niet uit levende wezens, maar uit de aarde muggen kwamen, Hoe niet de waterdieren, maar de Nijl kikvorsen spuwde.',
        11: 'Later zagen zij ook vogels op nieuwe wijze ontstaan, Toen zij uit zinnelust om lekkere spijzen vroegen;',
        12: 'Want om hun lust te voldoen, stegen er kwakkels op uit de zee.',
        13: 'En de straffen kwamen niet over de zondaars Zonder voorafgaande tekenen door felle bliksems. Het was immers billijk, dat ze leden voor hun boze daden, Daar ze de vreemdelingen vreselijk hadden gehaat.',
        14: 'Want terwijl anderen slechts onbekenden gastvrijheid weigerden, Hadden zij gasten, die weldoeners waren, tot slaven gemaakt.',
        15: 'Bovendien, voor de anderen is er nog een zekere verschoning, Daar zij de vreemdelingen aanstonds vijandig ontvingen;',
        16: 'Maar dezen namen hen eerst met vreugde op, En gaven hun dezelfde rechten, Doch verdrukten hen later met slavenwerk.',
        17: 'Daarom werden ook zij als met blindheid geslagen, Zoals die anderen aan de deur van den rechtvaardige, Toen ieder, in dichte duisternis gehuld, De toegang zocht naar zijn eigen deur.',
        18: 'Zo toonden de elementen zich telkens weer anders, Zoals bij een citer de tonen de aard van het rythme veranderen, Al behouden zij altijd dezelfde klank; Uit de feiten kan men dat duidelijk zien.',
        19: 'Want landdieren werden veranderd in waterdieren, En zwemmende dieren kwamen over het land;',
        20: 'Het vuur kreeg in het water nog groter kracht, En het water vergat zijn macht, om te blussen.',
    },
}
